window.docContents[239].resolve({"/StlcProp/#StlcProp":{"contents":"\n\n\n\n\n\nIn Wadler's \"PLF in Agda\", he defines an \"animator\" for STLC terms using the\nproof terms for progress + preservation.  This would be a FANTASTIC example\n(or, perhaps better, exercise!) for this chapter.\n\nIn this chapter, we develop the fundamental theory of the Simply\nTyped Lambda Calculus — in particular, the type safety\ntheorem.\n\nWe pick up where the Stlc chapter left off, so everything below\nlives in the same namespace as the definitions it is about.\n\nnamespace Stlc\n\nopen scoped MyGetElem\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Type Systems","header":"6. StlcProp: Properties of STLC","id":"/StlcProp/#StlcProp"},"/Types/#Type-Systems--Types___-Type-Systems--Typed-Arithmetic-Expressions--Syntax--Values":{"contents":"Values are true, false, and numeric values (0, and succ of a numeric value).\n\ninductive Tm.IsBValue : Tm → Prop where\n  | tru : Tm.IsBValue <{ true }>\n  | fls : Tm.IsBValue <{ false }>\n\ninductive Tm.IsNValue : Tm → Prop where\n  | zero : Tm.IsNValue <{ 0 }>\n  | succ (t : Tm) (h : Tm.IsNValue t) : Tm.IsNValue <{ succ t }>\n\ndef Tm.IsValue (t : Tm) : Prop := Tm.IsBValue t ∨ Tm.IsNValue t\n\n\n","context":"Type Systems\u0009Types: Type Systems\u0009Typed Arithmetic Expressions\u0009Syntax","header":"4.1.1.2. Values","id":"/Types/#Type-Systems--Types___-Type-Systems--Typed-Arithmetic-Expressions--Syntax--Values"}});